package com.marinainsaurralde.plango.model;
import java.util.Collections;import java.util.List;
public final class GrupoUbicacion {private final double latitud,longitud;private final List<Evento> eventos;public GrupoUbicacion(double lat,double lon,List<Evento> eventos){latitud=lat;longitud=lon;this.eventos=Collections.unmodifiableList(eventos);}public double getLatitud(){return latitud;}public double getLongitud(){return longitud;}public List<Evento> getEventos(){return eventos;}public int size(){return eventos.size();}public Evento getFirst(){return eventos.get(0);}public String getInstalacion(){for(Evento e:eventos)if(e.getNombreInstalacion()!=null&&!e.getNombreInstalacion().trim().isEmpty())return e.getNombreInstalacion();return null;}}
